import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function StudentNotes() {
  const navigate = useNavigate();
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login');
      return;
    }
    fetchNotes();
  }, [navigate]);

  const fetchNotes = async () => {
    try {
      setLoading(true);
      const response = await api.get('/api/student/grades');
      setNotes(response.data.grades || []);
    } catch (error) {
      console.error('Erreur chargement notes:', error);
      setError('Erreur lors du chargement des notes');
    } finally {
      setLoading(false);
    }
  };

  const handleBack = () => {
    navigate('/dashboard-student');
  };

  const getNoteColor = (note) => {
    if (note >= 16) return '#48bb78';
    if (note >= 12) return '#4299e1';
    if (note >= 10) return '#ed8936';
    return '#e53e3e';
  };

  const getNoteStatus = (note) => {
    if (note >= 10) return 'Admis';
    return 'Non admis';
  };

  const calculateStats = () => {
    if (notes.length === 0) return null;
    
    const total = notes.reduce((sum, note) => sum + parseFloat(note.note), 0);
    const moyenne = total / notes.length;
    const admis = notes.filter(note => note.note >= 10).length;
    const nonAdmis = notes.filter(note => note.note < 10).length;
    
    return {
      moyenne: moyenne.toFixed(2),
      admis,
      nonAdmis,
      total: notes.length
    };
  };

  const stats = calculateStats();

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.spinner}></div>
        <p>Chargement de vos notes...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <button onClick={handleBack} style={styles.backButton}>
          ← Retour au Dashboard
        </button>
        <h1 style={styles.title}>Mes Notes</h1>
        <div style={styles.headerActions}>
          <span style={styles.counter}>
            {notes.length} note{notes.length > 1 ? 's' : ''}
          </span>
        </div>
      </header>

      <main style={styles.main}>
        {error && (
          <div style={styles.errorAlert}>
            {error}
          </div>
        )}

        {stats && (
          <div style={styles.statsGrid}>
            <div style={styles.statCard}>
              <div style={styles.statNumber}>{stats.moyenne}</div>
              <div style={styles.statLabel}>Moyenne Générale</div>
            </div>
            <div style={styles.statCard}>
              <div style={{...styles.statNumber, color: '#48bb78'}}>{stats.admis}</div>
              <div style={styles.statLabel}>Notes ≥ 10</div>
            </div>
            <div style={styles.statCard}>
              <div style={{...styles.statNumber, color: '#e53e3e'}}>{stats.nonAdmis}</div>
              <div style={styles.statLabel}>Notes </div>
            </div>
            <div style={styles.statCard}>
              <div style={styles.statNumber}>{stats.total}</div>
              <div style={styles.statLabel}>Total des notes</div>
            </div>
          </div>
        )}

        {notes.length === 0 ? (
          <div style={styles.emptyState}>
            <div style={styles.emptyIcon}>📊</div>
            <h3>Aucune note disponible</h3>
            <p>Vos notes apparaîtront ici une fois publiées par vos professeurs.</p>
          </div>
        ) : (
          <div style={styles.notesTable}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Cours</th>
                  <th style={styles.th}>Niveau</th>
                  <th style={styles.th}>Note</th>
                  <th style={styles.th}>Statut</th>
                  <th style={styles.th}>Professeur</th>
                  <th style={styles.th}>Date</th>
                </tr>
              </thead>
              <tbody>
                {notes.map((note) => (
                  <tr key={note.id} style={styles.tr}>
                    <td style={styles.td}>
                      <strong>{note.course_title}</strong>
                    </td>
                    <td style={styles.td}>
                      <span style={styles.levelBadge}>{note.course_level}</span>
                    </td>
                    <td style={styles.td}>
                      <span 
                        style={{
                          ...styles.noteBadge,
                          background: getNoteColor(note.note)
                        }}
                      >
                        {note.note}/20
                      </span>
                    </td>
                    <td style={styles.td}>
                      <span 
                        style={{
                          ...styles.statusBadge,
                          background: note.note >= 10 ? '#c6f6d5' : '#fed7d7',
                          color: note.note >= 10 ? '#22543d' : '#742a2a'
                        }}
                      >
                        {getNoteStatus(note.note)}
                      </span>
                    </td>
                    <td style={styles.td}>{note.professeur_nom}</td>
                    <td style={styles.td}>
                      {new Date(note.date_evaluation).toLocaleDateString('fr-FR')}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </main>
    </div>
  );
}

// AJOUTER TOUS LES STYLES MANQUANTS
const styles = {
  container: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
  },
